#!/usr/bin/env node
/**
 * Tests for the search-engine meta files (robots.txt, sitemap.xml).
 *
 * The files are generated by build_meta.py and copied by build.mjs together
 * with every other produced file. What can silently rot here:
 *
 *   - the sitemap drifting from the real page set (a new generator forgets to
 *     be a page, or originals gain a document nobody advertises);
 *   - the sitemap advertising pages that must not be indexed (404 is served
 *     with a 404 status; a redirect entry would split the origin);
 *   - the sitemap growing a second origin, which teaches search engines that
 *     the site lives in two places.
 *
 * Every test that builds goes through SITE_DIR into a scratch directory, for
 * the same reason build.test.mjs does — the real docs/site is shared state.
 */
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { readdir, mkdtemp, rm, readFile } from 'node:fs/promises';
import { execFile } from 'node:child_process';
import { promisify } from 'node:util';
import { join, resolve, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';
import { tmpdir } from 'node:os';

const ROOT = resolve(dirname(fileURLToPath(import.meta.url)), '..', '..');
const BUILD = join(ROOT, 'scripts', 'site', 'build.mjs');
const ORIGIN = 'https://main.luteos.com';

const build = (siteDir) => promisify(execFile)(process.execPath, [BUILD], {
  env: { ...process.env, SITE_DIR: siteDir },
})
  .then((r) => ({ code: 0, out: r.stdout + r.stderr }))
  .catch((e) => ({ code: e.code ?? 1, out: (e.stdout ?? '') + (e.stderr ?? '') }));

async function withBuiltSite(run) {
  const site = await mkdtemp(join(tmpdir(), 'site-meta-'));
  try {
    const { code, out } = await build(site);
    assert.equal(code, 0, `build failed:\n${out}`);
    const robots = await readFile(join(site, 'robots.txt'), 'utf8');
    const sitemap = await readFile(join(site, 'sitemap.xml'), 'utf8');
    return await run({ robots, sitemap, site });
  } finally {
    await rm(site, { recursive: true, force: true });
  }
}

const sitemapUrls = (sitemap) => [...sitemap.matchAll(/<loc>([^<]+)<\/loc>/g)].map((m) => m[1]);

test('meta: robots.txt allows everything and points at the sitemap', async () => {
  await withBuiltSite(({ robots }) => {
    assert.match(robots, /^User-agent: \*\n/);
    assert.match(robots, /^Allow: \/$/m);
    assert.match(robots, /^Sitemap: https:\/\/main\.luteos\.com\/sitemap\.xml$/m);
  });
});

test('meta: sitemap lists exactly the public pages', async () => {
  await withBuiltSite(async ({ sitemap, site }) => {
    const urls = sitemapUrls(sitemap);
    assert.ok(urls.length > 0, 'sitemap is empty');
    // 与真实页面集合对账：根级 html（去掉 404 与 index 归一）+ originals。
    const root = (await readdir(join(ROOT, 'docs', 'site')))
      .filter((f) => f.endsWith('.html') && f !== '404.html' && f !== 'index.html')
      .map((f) => `${ORIGIN}/${f}`);
    const originals = (await readdir(join(ROOT, 'docs', 'site', 'originals')))
      .filter((f) => f.endsWith('.html'))
      .map((f) => `${ORIGIN}/originals/${f}`);
    const expected = [`${ORIGIN}/`, ...root.sort(), ...originals.sort()];
    assert.deepEqual(urls.sort(), expected.sort(), 'sitemap URL set drifted from the page set');
    // scratch 站点目录不该被误当 originals 来源：成员都在 ORIGIN 下。
    for (const u of urls) assert.ok(u.startsWith(`${ORIGIN}/`), u);
  });
});

test('meta: sitemap never advertises 404 or a second origin', async () => {
  await withBuiltSite(({ sitemap }) => {
    const urls = sitemapUrls(sitemap);
    assert.ok(!urls.some((u) => u.endsWith('/404.html')), '404 page is in the sitemap');
    const origins = new Set(urls.map((u) => new URL(u).origin));
    assert.deepEqual([...origins], ['https://main.luteos.com'], 'sitemap has a second origin');
  });
});

test('meta: output is byte-stable across rebuilds', async () => {
  const a = await mkdtemp(join(tmpdir(), 'site-meta-a-'));
  const b = await mkdtemp(join(tmpdir(), 'site-meta-b-'));
  try {
    const first = await build(a);
    const second = await build(b);
    assert.equal(first.code, 0, first.out);
    assert.equal(second.code, 0, second.out);
    for (const f of ['robots.txt', 'sitemap.xml']) {
      assert.equal(
        await readFile(join(a, f), 'utf8'),
        await readFile(join(b, f), 'utf8'),
        `${f} is not deterministic`,
      );
    }
  } finally {
    await rm(a, { recursive: true, force: true });
    await rm(b, { recursive: true, force: true });
  }
});
